// One website form submission becomes the lead record the processing workflow expects.
// The dedupe key covers who sent it and what they wrote, so a resubmitted form is recognised.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? {};
  const clean = (v) => (typeof v === 'string' ? v.trim() : '');
  const sent = Date.parse(b.received_at);  // test submissions may carry their own timestamp
  const input = {
    channel: 'web_form',
    received_at: Number.isNaN(sent) ? new Date().toISOString() : new Date(sent).toISOString(),
    name: clean(b.name), email: clean(b.email).toLowerCase(), phone: clean(b.phone),
    company: clean(b.company), message: clean(b.message),
  };
  if (!input.message || (!input.email && !input.phone)) continue;  // nothing to act on
  const key = ['form', input.email, input.phone.replace(/\D/g, ''), input.message.toLowerCase().replace(/\s+/g, ' ')].join('|');
  out.push({ json: { source: 'web_form', raw_key: key, received_at: input.received_at, input, reply_to: input.email || null, thread_id: null, message_id: null } });
}
return out;
